import{_ as s,o as e,c as t,a2 as o}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"十月之交","description":"","frontmatter":{"title":"十月之交","date":"2026-11-08T00:00:00.000Z","seq":33,"categories":["美文","诗经"],"collection":"《诗经 · 小雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·小雅/十月之交.md","filePath":"blogs/诗经·小雅/十月之交.md"}'),p={name:"blogs/诗经·小雅/十月之交.md"};function c(l,a,n,r,_,m){return e(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="十月之交" tabindex="-1">十月之交 <a class="header-anchor" href="#十月之交" aria-label="Permalink to &quot;十月之交&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　节南山之什</p><div class="poem"><p class="poem-stanza">十月之交，朔月辛卯。日有食之，亦孔之丑。彼月而微，此日而微；今此下民，亦孔之哀。</p><p class="poem-stanza">日月告凶，不用其行。四国无政，不用其良。彼月而食，则维其常；此日而食，于何不臧。</p><p class="poem-stanza">烨烨震电，不宁不令。百川沸腾，山冢崒崩。高岸为谷，深谷为陵。哀今之人，胡惨莫惩？</p><p class="poem-stanza">皇父卿士，番维司徒，家伯维宰，仲允膳夫，棸子内史，蹶维趣马，楀维师氏。醘妻煽方处。</p><p class="poem-stanza">抑此皇父，岂曰不时？胡为我作，不即我谋？彻我墙屋，田卒污莱。曰予不戕，礼则然矣。</p><p class="poem-stanza">皇父孔圣，作都于向。择三有事，亶侯多藏。不慭遗一老，俾守我王。择有车马，以居徂向。</p><p class="poem-stanza">黾勉从事，不敢告劳。无罪无辜，谗口嚣嚣。下民之孽，匪降自天。噂沓背憎，职竞由人。</p><p class="poem-stanza">悠悠我里，亦孔之痗。四方有羡，我独居忧。民莫不逸，我独不敢休。天命不彻，我不敢效我友自逸。</p></div>',3)])])}const u=s(p,[["render",c]]);export{d as __pageData,u as default};
